using UPM.Windows.Core;using Windows.Security.Credentials;
namespace UPM.SiteManager;
public sealed class CredentialVault:ICredentialVault{const string Resource="UPM.SiteManager.Session";public ValueTask SaveAsync(Guid id,string value,CancellationToken ct){ct.ThrowIfCancellationRequested();new PasswordVault().Add(new PasswordCredential(Resource,id.ToString("N"),value));return ValueTask.CompletedTask;}public ValueTask<string?> ReadAsync(Guid id,CancellationToken ct){ct.ThrowIfCancellationRequested();try{var c=new PasswordVault().Retrieve(Resource,id.ToString("N"));c.RetrievePassword();return ValueTask.FromResult<string?>(c.Password);}catch{return ValueTask.FromResult<string?>(null);}}public ValueTask ForgetAsync(Guid id,CancellationToken ct){ct.ThrowIfCancellationRequested();var v=new PasswordVault();try{v.Remove(v.Retrieve(Resource,id.ToString("N")));}catch{}return ValueTask.CompletedTask;}}
